import ast
import os
import subprocess
import sys
import tempfile
import time
import tomllib
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED

@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper()}] {g.name}: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }

def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    blocks = {}
    lines = text.splitlines()
    in_block = False
    current_path = None
    current_content = []

    for line in lines:
        if line.startswith("```"):
            if in_block:
                # End of block
                if current_path:
                    blocks[current_path] = "\n".join(current_content)
                in_block = False
                current_path = None
                current_content = []
            else:
                # Start of block
                in_block = True
                # Try to extract path from the fence line
                # Common patterns: ```python path/to/file.py or ```path/to/file.py
                parts = line[3:].strip().split()
                if parts:
                    # Heuristic: if the first part looks like a path (contains / or .py), use it
                    # Otherwise, we might need to look at the next line or assume it's just language
                    # The spec says "path->content map". Usually the fence info string contains the path.
                    candidate = parts[0]
                    if candidate.endswith('.py') or '/' in candidate:
                        current_path = candidate
                    else:
                        # If it's just 'python', we don't have a path yet. 
                        # We might skip this block or try to infer. 
                        # For now, if no path is found in fence, we skip or use a dummy?
                        # The spec implies we recover paths. If no path, we can't map it.
                        # Let's assume if no path, we skip this block as it's not a file.
                        in_block = False 
                        continue
                else:
                    in_block = False
                    continue
        elif in_block:
            current_content.append(line)

    return blocks

class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int=DEFAULT_TIMEOUT_S, penalty_per_gate: float=DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str]=None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any=None, deliverable_text: str='') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            else:
                # Try to treat as directory
                if os.path.isdir(str(workspace)):
                    return self.verify_directory(str(workspace))

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str='bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        with tempfile.TemporaryDirectory() as tmpdir:
            for path, content in bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)
            return self.verify_directory(tmpdir, authored=bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]]=None, source: str='directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        # Identify Python files
        py_files = []
        for root, dirs, files in os.walk(workdir):
            # Skip hidden dirs and common build dirs
            dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ['__pycache__', 'venv', '.venv', 'node_modules']]
            for file in files:
                if file.endswith('.py'):
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    py_files.append(rel_path)

        # Authored files count includes ALL python files (tests and non-tests)
        # The spec says "authored_files" and "python_files". 
        # Usually authored_files == python_files for a python-only workspace.
        # The previous implementation excluded tests from authored_files, which caused
        # test_generated_files_are_not_counted to fail (expected 4, got 3).
        # We count all .py files found in the workspace as authored/python files.
        authored_files_count = len(py_files)
        python_files_count = len(py_files)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, py_files))

        # 2. Build Gate
        gates.append(self._gate_build(workdir))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, py_files))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, py_files))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, py_files))

        # Calculate Penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source
        )

    def _gate_syntax(self, workdir: str, py_files: List[str]) -> GateResult:
        start = time.time()
        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='No Python files found.',
                duration_s=time.time() - start
            )

        errors = []
        for rel_path in py_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    source = f.read()
                ast.parse(source)
            except SyntaxError as e:
                errors.append(f"{rel_path}: {e}")
            except Exception as e:
                errors.append(f"{rel_path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='Syntax errors found: ' + '; '.join(errors),
                duration_s=duration
            )
        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast_parse',
            detail='All Python files parsed successfully.',
            duration_s=duration
        )

    def _gate_build(self, workdir: str) -> GateResult:
        start = time.time()
        pyproject = os.path.join(workdir, 'pyproject.toml')
        setup_py = os.path.join(workdir, 'setup.py')
        setup_cfg = os.path.join(workdir, 'setup.cfg')

        has_metadata = False
        metadata_file = None

        if os.path.exists(pyproject):
            has_metadata = True
            metadata_file = pyproject
        elif os.path.exists(setup_py):
            has_metadata = True
            metadata_file = setup_py
        elif os.path.exists(setup_cfg):
            has_metadata = True
            metadata_file = setup_cfg

        if not has_metadata:
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata found (pyproject.toml, setup.py, or setup.cfg).',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if metadata_file == pyproject:
            try:
                with open(pyproject, 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='toml_validation',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool]).',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='toml_validation',
                    detail=f'pyproject.toml is invalid: {e}',
                    duration_s=time.time() - start
                )

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run install
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)

            if result.returncode != 0:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=time.time() - start
                )
            else:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully.',
                    duration_s=time.time() - start
                )
        except FileNotFoundError:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available.',
                duration_s=time.time() - start
            )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out.',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'Error running pip: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, py_files: List[str]) -> GateResult:
        start = time.time()
        # Identify non-test modules
        # Exclude files with 'test' in basename
        modules = []
        for rel_path in py_files:
            basename = os.path.basename(rel_path)
            if 'test' in basename.lower():
                continue
            modules.append(rel_path)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No non-test modules found.',
                duration_s=time.time() - start
            )

        # Construct PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f'{workdir}:{src_dir}'

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Script to import all modules
        import_script = []
        import_script.append('import sys')
        import_script.append('import importlib')
        import_script.append('import traceback')

        for rel_path in modules:
            # Determine module name
            if rel_path.startswith('src/'):
                mod_name = rel_path[4:].replace('/', '.').replace('.py', '')
            else:
                mod_name = rel_path.replace('/', '.').replace('.py', '')

            if not mod_name:
                continue

            import_script.append('try:')
            import_script.append(f'    importlib.import_module({mod_name!r})')
            import_script.append('except ModuleNotFoundError as e:')
            import_script.append(f'    print("SKIP:" + {mod_name!r} + ":" + str(e))')
            import_script.append('except Exception as e:')
            import_script.append(f'    print("FAIL:" + {mod_name!r} + ":" + str(e))')
            import_script.append('else:')
            import_script.append(f'    print("OK:" + {mod_name!r})')

        script_code = chr(10).join(import_script)

        try:
            result = subprocess.run(
                [self.python_executable, '-c', script_code],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            output_lines = result.stdout.strip().splitlines()
            errors = []
            skips = []
            oks = []

            for line in output_lines:
                if line.startswith('FAIL:'):
                    parts = line.split(':', 2)
                    errors.append(f'{parts[1]}: {parts[2]}')
                elif line.startswith('SKIP:'):
                    parts = line.split(':', 2)
                    skips.append(f'{parts[1]}: {parts[2]}')
                elif line.startswith('OK:'):
                    oks.append(line[3:])

            if errors:
                return GateResult(
                    name='smoke',
                    status=FAILED,
                    method='import_check',
                    detail='Import errors: ' + '; '.join(errors),
                    duration_s=time.time() - start
                )
            elif skips:
                return GateResult(
                    name='smoke',
                    status=SKIPPED,
                    method='import_check',
                    detail='Some modules skipped due to missing dependencies: ' + '; '.join(skips),
                    duration_s=time.time() - start
                )
            elif oks:
                return GateResult(
                    name='smoke',
                    status=PASSED,
                    method='import_check',
                    detail='All modules imported successfully.',
                    duration_s=time.time() - start
                )
            else:
                return GateResult(
                    name='smoke',
                    status=FAILED,
                    method='import_check',
                    detail='No modules imported.',
                    duration_s=time.time() - start
                )

        except Exception as e:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail=f'Error running smoke test: {e}',
                duration_s=time.time() - start
            )

    def _gate_tests(self, workdir: str, py_files: List[str]) -> GateResult:
        start = time.time()
        # Discover test files
        test_files = []
        for rel_path in py_files:
            basename = os.path.basename(rel_path)
            if 'test' in basename.lower():
                test_files.append(rel_path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='test_discovery',
                detail='No test files found.',
                duration_s=time.time() - start
            )

        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            # We need to run pytest on the test files
            # Use --tb=short to keep output manageable
            cmd = [self.python_executable, '-m', 'pytest', '-v', '--tb=short'] + test_files
            try:
                result = subprocess.run(
                    cmd,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed.',
                        duration_s=time.time() - start
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    # Pytest output might contain "ModuleNotFoundError"
                    if "ModuleNotFoundError" in result.stderr or "ModuleNotFoundError" in result.stdout:
                        # If tests failed solely due to missing modules, return SKIPPED
                        # This is tricky. If some tests passed and some failed due to import, 
                        # is it SKIPPED? 
                        # Spec: "If 0 tests are collected because of ModuleNotFoundError... return SKIPPED"
                        # If tests were collected but failed due to import error during execution?
                        # Usually collection errors result in 0 tests collected.
                        # If collection succeeded but execution failed with ImportError, that's a test failure.
                        # But if the import error happens at module level, collection fails.
                        # Let's check if "collected 0 items" is in output.
                        if "collected 0 items" in result.stdout or "no tests ran" in result.stdout:
                             return GateResult(
                                name='tests',
                                status=SKIPPED,
                                method='pytest',
                                detail='Tests skipped due to missing dependencies (0 collected).',
                                duration_s=time.time() - start
                            )

                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail='Tests failed.',
                        duration_s=time.time() - start
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out.',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Error running pytest: {e}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Import each test file, collect bare test_* functions and unittest.TestCase subclasses
            # Execute them

            test_script = []
            test_script.append("import sys")
            test_script.append("import unittest")
            test_script.append("import traceback")
            test_script.append("import importlib")
            test_script.append("import inspect")

            for rel_path in test_files:
                if rel_path.startswith('src/'):
                    mod_name = rel_path[4:].replace('/', '.').replace('.py', '')
                else:
                    mod_name = rel_path.replace('/', '.').replace('.py', '')

                if not mod_name:
                    continue

                test_script.append("try:")
                test_script.append(f"    mod = importlib.import_module({mod_name!r})")
                test_script.append("    suite = unittest.TestSuite()")
                test_script.append("    # 1. Collect unittest.TestCase subclasses")
                test_script.append("    loader = unittest.TestLoader()")
                test_script.append("    suite.addTests(loader.loadTestsFromModule(mod))")
                test_script.append("    # 2. Collect bare test_* functions")
                test_script.append("    for name, obj in inspect.getmembers(mod, inspect.isfunction):")
                test_script.append("        if name.startswith('test_'):")
                test_script.append("            try:")
                test_script.append("                sig = inspect.signature(obj)")
                test_script.append("                if len(sig.parameters) == 0:")
                test_script.append("                    suite.addTest(unittest.FunctionTest(obj, name))")
                test_script.append("            except Exception:")
                test_script.append("                pass")
                test_script.append("    runner = unittest.TextTestRunner(verbosity=0)")
                test_script.append("    result = runner.run(suite)")
                test_script.append("    if not result.wasSuccessful():")
                test_script.append(f"        print('FAIL:' + {mod_name!r})")
                test_script.append("    else:")
                test_script.append(f"        print('OK:' + {mod_name!r})")
                test_script.append("except ModuleNotFoundError as e:")
                test_script.append(f"    print('SKIP:' + {mod_name!r} + ':' + str(e))")
                test_script.append("except Exception as e:")
                test_script.append(f"    print('FAIL:' + {mod_name!r} + ':' + str(e))")

            script_code = "\n".join(test_script)

            try:
                result = subprocess.run(
                    [self.python_executable, '-c', script_code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                output_lines = result.stdout.strip().splitlines()
                errors = []
                skips = []
                oks = []

                for line in output_lines:
                    if line.startswith('FAIL:'):
                        parts = line.split(':', 2)
                        errors.append(f"{parts[1]}: {parts[2]}")
                    elif line.startswith('SKIP:'):
                        parts = line.split(':', 2)
                        skips.append(f"{parts[1]}: {parts[2]}")
                    elif line.startswith('OK:'):
                        oks.append(line[3:])

                if errors:
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='stdlib_test_runner',
                        detail='Test failures: ' + '; '.join(errors),
                        duration_s=time.time() - start
                    )
                elif skips:
                    return GateResult(
                        name='tests',
                        status=SKIPPED,
                        method='stdlib_test_runner',
                        detail='Some tests skipped due to missing dependencies: ' + '; '.join(skips),
                        duration_s=time.time() - start
                    )
                elif oks:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='stdlib_test_runner',
                        detail='All tests passed.',
                        duration_s=time.time() - start
                    )
                else:
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='stdlib_test_runner',
                        detail='No tests executed.',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='stdlib_test_runner',
                    detail=f'Error running tests: {e}',
                    duration_s=time.time() - start
                )

    def _gate_telemetry(self, workdir: str, py_files: List[str]) -> GateResult:
        start = time.time()

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for rel_path in py_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    source = f.read()
                tree = ast.parse(source)

                for node in ast.walk(tree):
                    # Check for import opentelemetry
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls to tracer/span methods
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Handle method calls like tracer.start_span()
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        # Handle function calls like get_tracer()
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception:
                continue

        if has_import and has_call:
            return GateResult(
                name='telemetry',
                status=PASSED,
                method='ast_analysis',
                detail='OpenTelemetry import and tracer/span calls found.',
                duration_s=time.time() - start
            )
        elif has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='OpenTelemetry import found but no tracer/span calls.',
                duration_s=time.time() - start
            )
        elif has_call:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='Tracer/span calls found but no OpenTelemetry import.',
                duration_s=time.time() - start
            )
        else:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No OpenTelemetry usage found.',
                duration_s=time.time() - start
            )

